NAME = re.compile(r"^[A-Z][A-Z0-9_]{1,127}$")
ALLOWED = {
    ("mistral", "chat-completions", "https://api.mistral.ai/v1/chat/completions", "mistral-hosted-fictitious-fixture"): "MISTRAL_API_KEY",
    ("ollama", "native-local-chat", "http://127.0.0.1:11434/api/chat", "qwen-family-local-fictitious-fixture"): None,
}
OUTPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "category": {"type": "string", "enum": ["billing", "access", "bug", "other"]},
        "priority": {"type": "integer", "minimum": 1, "maximum": 5},
