def json_value(value):
    if value is None or isinstance(value, (str, bool, int)):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite number")
        return
    if isinstance(value, list):
        for item in value:
            json_value(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise TypeError("non-string JSON key")
            json_value(item)
        return
    raise TypeError("unsupported JSON value")


def _validate(config, secrets, allow_fallback=False):
    json_value(config)
    if not isinstance(config, dict) or not isinstance(secrets, dict):
        raise TypeError("config and resolver must be objects")
    top = {"version", "application", "data_policy", "primary", "fallback", "limits", "providers"}
    if set(config) != top:
        raise ValueError("wrong top-level fields")
    for key in ("version", "application"):
        if not isinstance(config[key], str) or not config[key].strip():
            raise ValueError("blank application identity")

    policy = config["data_policy"]
    policy_fields = {"classification", "region", "retention_owner", "retention"}
    if not isinstance(policy, dict) or set(policy) != policy_fields:
        raise ValueError("invalid data policy")
    if any(not isinstance(policy[k], str) or not policy[k].strip() for k in policy_fields):
        raise ValueError("blank data-policy value")

    limits = config["limits"]
    limit_fields = {"timeout_seconds", "max_retries", "overall_budget_seconds"}
    if not isinstance(limits, dict) or set(limits) != limit_fields:
        raise ValueError("invalid limits")
    for key in limit_fields:
        if isinstance(limits[key], bool) or not isinstance(limits[key], int) or limits[key] < 0:
            raise ValueError("limits must be nonnegative integers")
    if limits["timeout_seconds"] == 0:
        raise ValueError("timeout must be positive")
    if limits["timeout_seconds"] * (limits["max_retries"] + 1) > limits["overall_budget_seconds"]:
        raise ValueError("primary attempt budget exceeded")

    providers = config["providers"]
    provider_fields = {
        "id", "provider", "interface", "endpoint", "model", "secret_env", "allow_redirects",
        "capability_receipt", "capability_receipt_version", "data_policy_evidence"
    }
    if not isinstance(providers, list) or not providers:
        raise ValueError("nonempty providers list required")
    ids = set()
    for provider in providers:
        if not isinstance(provider, dict) or set(provider) != provider_fields:
            raise ValueError("invalid provider fields")
        if not isinstance(provider["id"], str) or not provider["id"].strip() or provider["id"] in ids:
            raise ValueError("missing or duplicate provider identity")
        ids.add(provider["id"])
        tuple_names = ("provider", "interface", "endpoint", "model")
        if any(not isinstance(provider[k], str) or not provider[k].strip() for k in tuple_names):
            raise ValueError("provider tuple fields must be nonempty strings")
        tuple_key = tuple(provider[k] for k in tuple_names)
        if tuple_key not in ALLOWED:
            raise ValueError("unsupported provider tuple")
        parsed = urlparse(provider["endpoint"])
        if (parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or
                parsed.password or parsed.query or parsed.fragment):
            raise ValueError("unsafe endpoint")
        if provider["allow_redirects"] is not False:
            raise ValueError("redirects must be disabled")
        expected_env = ALLOWED[tuple_key]
        if provider["secret_env"] != expected_env:
            raise ValueError("wrong secret environment name")
        if expected_env is not None:
            value = secrets.get(expected_env)
            if not NAME.fullmatch(expected_env) or not isinstance(value, str) or not value:
                raise ValueError("missing secret resolver input")
        for key in ("capability_receipt", "capability_receipt_version", "data_policy_evidence"):
            if not isinstance(provider[key], str) or not provider[key].strip():
                raise ValueError("blank evidence")

    by_id = {provider["id"]: provider for provider in providers}
    if not isinstance(config["primary"], str) or config["primary"] not in by_id:
        raise ValueError("invalid primary")

    fallback = config["fallback"]
    base_fields = {"enabled", "target", "approval_id", "reason"}
    extended_fields = base_fields | {"fallback_capability_evidence", "fallback_data_policy_evidence"}
    if not isinstance(fallback, dict):
        raise ValueError("fallback must be an object")
    fallback_fields = set(fallback)
    if not allow_fallback and fallback_fields != base_fields:
        raise ValueError("original fallback requires four fields")
    if allow_fallback and fallback_fields != base_fields and fallback_fields != extended_fields:
        raise ValueError("invalid fallback fields")
    if not isinstance(fallback["enabled"], bool):
        raise ValueError("fallback enabled must be boolean")
    if not isinstance(fallback["reason"], str) or not fallback["reason"].strip():
        raise ValueError("invalid fallback reason")
    if not fallback["enabled"]:
        if fallback_fields != base_fields:
            raise ValueError("disabled fallback cannot carry approval evidence")
        if fallback["target"] is not None or fallback["approval_id"] is not None:
            raise ValueError("disabled fallback target and approval must be null")
    else:
        if not allow_fallback or fallback_fields != extended_fields:
            raise ValueError("enabled fallback is not allowed by this validator")
        target = fallback["target"]
        if not isinstance(target, str) or target not in by_id or target == config["primary"]:
            raise ValueError("invalid fallback target")
        if not isinstance(fallback["approval_id"], str) or not fallback["approval_id"].strip():
            raise ValueError("missing fallback approval")
        for key in ("fallback_capability_evidence", "fallback_data_policy_evidence"):
            if not isinstance(fallback[key], str) or not fallback[key].strip():
                raise ValueError("missing fallback evidence")
    return copy.deepcopy(config)


def validate_config(config, secrets):
    return _validate(config, secrets, allow_fallback=False)


def build_request(config, messages, secrets):
    checked = validate_config(config, secrets)
    if not isinstance(messages, list) or not messages:
        raise ValueError("nonempty messages list required")
    for message in messages:
        if not isinstance(message, dict) or set(message) != {"role", "content"}:
            raise ValueError("invalid message fields")
        if message["role"] not in {"system", "user", "assistant"}:
            raise ValueError("invalid message role")
        if not isinstance(message["content"], str) or not message["content"].strip():
            raise ValueError("invalid message content")
    provider = next(p for p in checked["providers"] if p["id"] == checked["primary"])
    body = {"model": provider["model"], "messages": copy.deepcopy(messages), "stream": False}
    if provider["provider"] == "mistral":
        body["response_format"] = {
            "type": "json_schema", "json_schema": {"name": "ticket", "schema": OUTPUT_SCHEMA}
        }
    else:
        body["format"] = OUTPUT_SCHEMA
    return {
        "endpoint": provider["endpoint"], "interface": provider["interface"],
        "auth_env": provider["secret_env"], "allow_redirects": False, "body": body
    }


def validate_output(text):
    value = json.loads(text)
    if not isinstance(value, dict) or set(value) != {"category", "priority", "trace_id"}:
        raise ValueError("wrong output fields")
    if value["category"] not in {"billing", "access", "bug", "other"}:
        raise ValueError("invalid category")
    if isinstance(value["priority"], bool) or not isinstance(value["priority"], int):
        raise ValueError("priority must be an integer")
    if not 1 <= value["priority"] <= 5:
        raise ValueError("priority outside domain")
    if not isinstance(value["trace_id"], str) or not value["trace_id"].strip():
        raise ValueError("invalid trace")
    return copy.deepcopy(value)


def safe_fingerprint(config, secrets):
    checked = validate_config(config, secrets)
    redacted = copy.deepcopy(checked)
    for provider in redacted["providers"]:
        if provider["secret_env"] is not None:
            provider["secret_env"] = "SECRET_REF"
    payload = json.dumps(redacted, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def create_new_config(path, config, secrets):
    checked = validate_config(config, secrets)
    serialized = json.dumps(checked, sort_keys=True, separators=(",", ":"))
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be path-like")
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(serialized)
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        raise

import copy
from reference import _validate


def validate_config_with_approved_fallback(config, secrets):
    checked = _validate(config, secrets, allow_fallback=True)
    fallback = checked["fallback"]
    if not fallback["enabled"]:
        return copy.deepcopy(checked)
    limits = checked["limits"]
    attempts = limits["max_retries"] + 2
    worst_case_seconds = limits["timeout_seconds"] * attempts
    if worst_case_seconds > limits["overall_budget_seconds"]:
        raise ValueError("primary plus fallback exceeds total budget")
    return copy.deepcopy(checked)
